def gen(rng):
    M = {}
    for ch, d in zip('abcdefghijklmnopqrstuvwxyz', '22233344455566677778889999'):
        M[ch] = d
    def code(w):
        return ''.join(M[c] for c in w)
    def fmt(words, ops):
        return str(len(words)) + '\n' + '\n'.join(words) + ('\n' if words else '') + str(len(ops)) + '\n' + '\n'.join(a + ' ' + b for a, b in ops)
    tests = [
        fmt(['careers', 'linkedin', 'hiring', 'interview', 'linkedgo'], [('QUERY', '2273377'), ('QUERY', '54653346')]),
        fmt([], [('QUERY', '2'), ('ADD', 'a'), ('QUERY', '2'), ('REMOVE', 'a'), ('QUERY', '2')]),
        fmt(['a', 'b', 'c', 'd'], [('QUERY', '2'), ('REMOVE', 'b'), ('QUERY', '2'), ('REMOVE', 'b'), ('ADD', 'a'), ('QUERY', '2'), ('QUERY', '3'), ('QUERY', '1')]),
        fmt(['abc', 'bcd', 'cab'], [('QUERY', '222'), ('QUERY', '0'), ('QUERY', '2221'), ('QUERY', '999')]),
        fmt(['hello', 'world', 'jello'], [('QUERY', '43556'), ('ADD', 'gdkkn'), ('QUERY', '43556'), ('REMOVE', 'jello'), ('QUERY', '43556'), ('ADD', 'jello'), ('QUERY', '43556')]),
    ]
    alpha = 'abcdgjmpt'
    for _ in range(14):
        base = [''.join(rng.choice(alpha) for _ in range(rng.randint(1, 3))) for _ in range(rng.randint(0, 6))]
        pool = base[:]
        ops = []
        for _ in range(rng.randint(1, 18)):
            k = rng.choice(['ADD', 'REMOVE', 'QUERY', 'QUERY'])
            if k == 'QUERY':
                if pool and rng.random() < 0.8:
                    ops.append(('QUERY', code(rng.choice(pool))))
                else:
                    ops.append(('QUERY', ''.join(rng.choice('0123456789') for _ in range(rng.randint(1, 3)))))
            else:
                if k == 'ADD' or not pool:
                    w = ''.join(rng.choice(alpha) for _ in range(rng.randint(1, 3)))
                    pool.append(w)
                else:
                    w = rng.choice(pool)
                ops.append((k, w))
        tests.append(fmt(base, ops))
    letters = 'abcdefghijklmnopqrstuvwxyz'
    def big(m, q, wl, alphabet, qshare):
        base = [''.join(rng.choice(alphabet) for _ in range(rng.randint(*wl))) for _ in range(m)]
        pool = base[:]
        ops = []
        for _ in range(q):
            r = rng.random()
            if r < qshare:
                ops.append(('QUERY', code(rng.choice(pool))))
            elif r < qshare + (1 - qshare) / 2:
                w = ''.join(rng.choice(alphabet) for _ in range(rng.randint(*wl)))
                pool.append(w)
                ops.append(('ADD', w))
            else:
                ops.append(('REMOVE', rng.choice(pool)))
        return fmt(base, ops)
    tests.append(big(50000, 50000, (3, 8), letters, 0.34))
    tests.append(big(50000, 50000, (5, 20), letters, 0.5))
    tests.append(big(50000, 50000, (2, 4), letters, 0.34))
    tests.append(big(20000, 3000, (4, 5), 'abcdefghi', 0.9))
